func TestCheckProxyAddr(t *testing.T) {
	makeProxy := func(addr string) services.Server {
		return &services.ServerV2{Spec: services.ServerSpecV2{PublicAddr: addr}}
	}
	tests := []struct {
		name     string
		cfg      *service.Config
		proxies  []services.Server
		override string
		want     string
		fail     bool
	}{
		{"local kube", &service.Config{Proxy: service.ProxyConfig{Kube: service.KubeProxyConfig{Enabled: true, PublicAddrs: []utils.NetAddr{{Addr: "kube.example.com:9999"}}}, PublicAddrs: []utils.NetAddr{{Addr: "web.example.com:3080"}}}}, nil, "", "https://kube.example.com:3026", false},
		{"registered proxy", &service.Config{}, []services.Server{makeProxy("bad/path"), makeProxy("web.example.com:3080")}, "", "https://web.example.com:3026", false},
		{"explicit proxy", &service.Config{}, nil, "https://custom.example.com:4444", "https://custom.example.com:4444", false},
		{"invalid proxies", &service.Config{}, []services.Server{makeProxy("bad/path")}, "", "", true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			ac := &AuthCommand{config: tt.cfg, outputFormat: identityfile.FormatKubernetes, proxyAddr: tt.override}
			err := ac.checkProxyAddr(mockClient{proxies: tt.proxies})
			if (err != nil) != tt.fail || ac.proxyAddr != tt.want {
				t.Fatalf("checkProxyAddr() = %q, %v; want %q, error=%v", ac.proxyAddr, err, tt.want, tt.fail)
			}
		})
	}
}

